// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeAggregateCompiler.safeResourceId;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.common.annotation.Experimental;
import org.eclipse.rdf4j.query.algebra.Compare;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeKernelIr.Kernel;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeKernelIr.Node;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeKernelIr.Operand;

/**
 * General lowering pass from compiled {@code SlotPlan} trees to kernel IR (plan:
 * plans/lmdb-native-engine/20-kernel-lowering-row.md, M1). Pure recognition: no store access, no probe — the output is
 * a shape-keyed {@link Kernel} plus a {@link LmdbNativeKernelBindings} descriptor the execution rung binds per open. M1
 * scope is {@code MultiJoinPlan} roots (constant-predicate patterns chained through known endpoints, VALUES / folded-IN
 * seeds, correlated entry slots) with the three filter tiers: id-inline (equality soundness identical to the
 * shape-specific recognizer), hook-callback (any {@code NativeBooleanFilter} whose read mask covers at most three
 * kernel-visible slots), and wrapper-residual. A filter alone never declines a lowering; unsupported structure does,
 * with the reason recorded against {@code PATH_IR_KERNEL}.
 */
@Experimental
final class LmdbNativeKernelLowering {

	private static final int MAX_CHILDREN = 12;
	private static final int MAX_HOOK_ARGS = 3;

	private LmdbNativeKernelLowering() {
	}

	static final class Lowered {
		final Kernel kernel;
		final LmdbNativeKernelBindings bindings;

		Lowered(Kernel kernel, LmdbNativeKernelBindings bindings) {
			this.kernel = kernel;
			this.bindings = bindings;
		}
	}

	/** Lowers a row-producing plan; null means declined (reason recorded against the decline target). */
	static Lowered lowerRows(SlotPlan arg, RowState row, TupleExpr declineTarget) {
		// OPTIONAL chains nest left-deep: LeftJoin(LeftJoin(core, r1), r2) applies r1 then r2 — peel arms in
		// application order, along with any FilterPlan wrappers (group-level filters over the optional vars),
		// which degrade through the ordinary three tiers (plan 22, M3).
		List<SlotPlan> optionalArms = new ArrayList<>(0);
		List<MaskedFilter> outerFilters = new ArrayList<>(0);
		SlotPlan core = arg;
		while (true) {
			if (core instanceof LeftJoinPlan) {
				LeftJoinPlan leftJoin = (LeftJoinPlan) core;
				optionalArms.add(0, leftJoin.right);
				core = leftJoin.left;
			} else if (core instanceof FilterPlan) {
				FilterPlan filterPlan = (FilterPlan) core;
				outerFilters.add(new MaskedFilter(filterPlan.filter, filterPlan.filterMask));
				core = filterPlan.arg;
			} else {
				break;
			}
		}
		if (!(core instanceof MultiJoinPlan)) {
			decline(declineTarget, "unsupported:" + core.getClass().getSimpleName());
			return null;
		}
		return lowerMultiJoin((MultiJoinPlan) core, optionalArms, outerFilters, row, declineTarget);
	}

	/**
	 * Lowers a whole native aggregation (plan 21): producer bag, EXISTS/NOT-EXISTS witness filters as short-circuit
	 * sub-pipelines, and an Aggregate terminal from the specs. Unlike the row side there is no residual surface — the
	 * aggregate consumer applies no per-row wrapper — so every filter must lower (id, hook, or witness) or the whole
	 * lowering declines.
	 */
	static Lowered lowerAggregate(SlotPlan arg, RowState row, int[] groupSlots, AggregateSpec[] aggregates,
			TupleExpr declineTarget) {
		// Sticky (EXISTS-bearing) filters never flatten into a MultiJoinPlan — they arrive as FilterPlan wrappers
		// around the producer. Peel the wrapper chain, collecting the conditions, then lower the core.
		List<MaskedFilter> filters = new ArrayList<>();
		List<SlotPlan> minusArms = new ArrayList<>();
		SlotPlan core = arg;
		while (true) {
			if (core instanceof FilterPlan) {
				FilterPlan filterPlan = (FilterPlan) core;
				filters.add(new MaskedFilter(filterPlan.filter, filterPlan.filterMask));
				core = filterPlan.arg;
			} else if (core instanceof MinusPlan) {
				// MINUS with shared variables is an anti-join on those variables; the factory already drops
				// disjoint-domain MINUS (identity), so a constructed MinusPlan always correlates.
				MinusPlan minus = (MinusPlan) core;
				minusArms.add(minus.right);
				core = minus.left;
			} else {
				break;
			}
		}
		SlotPlan[] children;
		if (core instanceof MultiJoinPlan) {
			MultiJoinPlan multiJoin = (MultiJoinPlan) core;
			children = multiJoin.derivedPlan(row).order;
			filters.addAll(java.util.Arrays.asList(multiJoin.filters));
		} else if (core instanceof PatternPlan || core instanceof MultiValuePatternPlan
				|| core instanceof ValuesPlan) {
			children = new SlotPlan[] { core };
		} else {
			decline(declineTarget, "agg:unsupported:" + core.getClass().getSimpleName());
			return null;
		}
		if (children.length == 0 || children.length > MAX_CHILDREN) {
			decline(declineTarget, children.length == 0 ? "agg:no-children" : "agg:too-many-children");
			return null;
		}
		Builder builder = new Builder(row);
		for (SlotPlan child : children) {
			boolean lowered;
			if (child instanceof PatternPlan) {
				lowered = builder.lowerPattern((PatternPlan) child);
			} else if (child instanceof MultiValuePatternPlan) {
				lowered = builder.lowerMultiValuePattern((MultiValuePatternPlan) child);
			} else if (child instanceof ValuesPlan) {
				lowered = builder.lowerValues((ValuesPlan) child);
			} else {
				builder.reason = "agg:child:" + child.getClass().getSimpleName();
				lowered = false;
			}
			if (!lowered) {
				decline(declineTarget, builder.reason);
				return null;
			}
		}
		for (MaskedFilter masked : filters) {
			if (!builder.lowerFilterStrict(masked)) {
				decline(declineTarget, builder.reason);
				return null;
			}
		}
		for (SlotPlan minusArm : minusArms) {
			if (!builder.lowerMinusArm(minusArm)) {
				decline(declineTarget, builder.reason);
				return null;
			}
		}
		Lowered lowered = builder.buildAggregate(groupSlots, aggregates);
		if (lowered == null) {
			decline(declineTarget, builder.reason);
		}
		return lowered;
	}

	// ------------------------------------------------------------------
	// MultiJoinPlan lowering
	// ------------------------------------------------------------------

	private static Lowered lowerMultiJoin(MultiJoinPlan multiJoin, List<SlotPlan> optionalArms,
			List<MaskedFilter> outerFilters, RowState row, TupleExpr declineTarget) {
		MultiJoinPlan.OrderedPlan ordered = multiJoin.derivedPlan(row);
		SlotPlan[] order = ordered.order;
		if (order.length == 0 || order.length > MAX_CHILDREN) {
			decline(declineTarget, order.length == 0 ? "no-children" : "too-many-children");
			return null;
		}
		Builder builder = new Builder(row);
		for (SlotPlan child : order) {
			boolean lowered;
			if (child instanceof PatternPlan) {
				lowered = builder.lowerPattern((PatternPlan) child);
			} else if (child instanceof MultiValuePatternPlan) {
				lowered = builder.lowerMultiValuePattern((MultiValuePatternPlan) child);
			} else if (child instanceof ValuesPlan) {
				lowered = builder.lowerValues((ValuesPlan) child);
			} else {
				builder.reason = "child:" + child.getClass().getSimpleName();
				lowered = false;
			}
			if (!lowered) {
				decline(declineTarget, builder.reason);
				return null;
			}
		}
		for (SlotPlan arm : optionalArms) {
			if (!builder.lowerOptionalArm(arm)) {
				decline(declineTarget, builder.reason);
				return null;
			}
		}
		for (MaskedFilter masked : multiJoin.filters) {
			builder.lowerFilter(masked);
		}
		for (MaskedFilter masked : outerFilters) {
			builder.lowerFilter(masked);
		}
		Lowered lowered = builder.build();
		if (lowered == null) {
			decline(declineTarget, "no-columns");
		}
		return lowered;
	}

	private static void decline(TupleExpr declineTarget, String reason) {
		if (Boolean.getBoolean("rdf4j.lmdb.janinoCodegen.debug")) {
			System.err.println("[ir-lowering] decline: " + reason);
		}
		LmdbNativeAttemptMetrics.recordDecline(declineTarget, LmdbNativeAttemptMetrics.PATH_IR_KERNEL, reason);
	}

	// ------------------------------------------------------------------
	// Builder state
	// ------------------------------------------------------------------

	private static final class Builder {
		final RowState row;
		final long entryMask;
		long assuredMask;
		String reason = "unknown";

		final List<List<Node>> nodesPerDepth = new ArrayList<>(); // nodes contributed by producer depth d
		final List<Node> entryDepthFilters = new ArrayList<>(); // filters decidable before any producer
		final List<List<Node>> filtersPerDepth = new ArrayList<>();

		final List<Long> constants = new ArrayList<>();
		final List<Integer> entrySlotIds = new ArrayList<>();
		final List<LmdbNativeKernelBindings.DomainRequest> keyDomains = new ArrayList<>();

		private boolean slotFresh(int slot) {
			return slot >= 0 && slot < slotColumn.length && (entryMask >>> slot & 1L) == 0L
					&& slotColumn[slot] < 0;
		}

		/** Kernel columns that may hold NULL (-1): produced by OPTIONAL arms. Indexed by column ordinal. */
		long optionalColMask;

		private boolean operandMaybeNull(Operand operand) {
			return operand.kind == Operand.COL && (optionalColMask >>> operand.index & 1L) == 1L;
		}

		/**
		 * OPTIONAL arm (plan 22, M3 v1): a bare single pattern with one already-available endpoint and one fresh slot
		 * lowers to a LeftProbe (null arm sets -1). Condition-bearing (FilterPlan-wrapped), multi-pattern, and other
		 * shapes decline — join-condition semantics need a future LeftGroup container.
		 */
		boolean lowerOptionalArm(SlotPlan arm) {
			if (!(arm instanceof PatternPlan)) {
				reason = "optional-arm:" + arm.getClass().getSimpleName();
				return false;
			}
			PatternPlan pattern = (PatternPlan) arm;
			if (pattern.hasRepeatedSlot() || pattern.namedContextScope || !pattern.p.isConstant()
					|| pattern.p.hasSlot() || pattern.c.hasSlot() || pattern.c.isConstant()
					|| pattern.contexts.isFixed() || pattern.s.bindConstant || pattern.o.bindConstant
					|| pattern.statementOrder != null) {
				reason = "optional-arm-guards";
				return false;
			}
			Operand subject = operandOf(pattern.s);
			Operand object = operandOf(pattern.o);
			// A key that is itself optional would need non-well-designed scan semantics when null — decline.
			if ((subject != null && operandMaybeNull(subject)) || (object != null && operandMaybeNull(object))) {
				reason = "optional-chained-on-optional";
				return false;
			}
			if (subject != null && object == null && pattern.o.hasSlot() && slotFresh(pattern.o.slot)) {
				openDepth();
				int adj = adjacency(pattern.p.constant, true, false);
				int column = newColumn(pattern.o.slot);
				optionalColMask |= 1L << column;
				currentDepthNodes().add(new LmdbNativeKernelIr.LeftProbe(adj, subject, column));
				return true;
			}
			if (object != null && subject == null && pattern.s.hasSlot() && slotFresh(pattern.s.slot)) {
				openDepth();
				int adj = adjacency(pattern.p.constant, false, false);
				int column = newColumn(pattern.s.slot);
				optionalColMask |= 1L << column;
				// never resource-assured: the null arm leaves the column unbound
				currentDepthNodes().add(new LmdbNativeKernelIr.LeftProbe(adj, object, column));
				return true;
			}
			reason = "optional-arm-shape";
			return false;
		}

		final List<LmdbNativeKernelBindings.AdjacencyRequest> adjacencies = new ArrayList<>();
		final List<LmdbNativeKernelBindings.FilterHook> filterHooks = new ArrayList<>();
		final List<Integer> columnEngineSlots = new ArrayList<>();
		final List<MaskedFilter> residualFilters = new ArrayList<>();

		final int[] slotColumn;
		final int[] slotColumnDepth;

		Builder(RowState row) {
			this.row = row;
			this.entryMask = row.boundMask();
			this.slotColumn = new int[row.slots.length];
			this.slotColumnDepth = new int[row.slots.length];
			java.util.Arrays.fill(slotColumn, -1);
		}

		private int depth() {
			return nodesPerDepth.size() - 1;
		}

		private List<Node> currentDepthNodes() {
			return nodesPerDepth.get(nodesPerDepth.size() - 1);
		}

		private void openDepth() {
			nodesPerDepth.add(new ArrayList<>());
			filtersPerDepth.add(new ArrayList<>());
		}

		private int newColumn(int engineSlot) {
			columnEngineSlots.add(engineSlot);
			int column = columnEngineSlots.size() - 1;
			slotColumn[engineSlot] = column;
			slotColumnDepth[engineSlot] = depth();
			return column;
		}

		private int constantIndex(long id) {
			constants.add(id);
			return constants.size() - 1;
		}

		private int adjacency(long predicate, boolean bySubject, boolean needsKeyEnum) {
			adjacencies.add(new LmdbNativeKernelBindings.AdjacencyRequest(predicate, bySubject, needsKeyEnum));
			return adjacencies.size() - 1;
		}

		/** Classifies a term as an available operand, or null when it is fresh (or unusable). */
		private Operand operandOf(Term term) {
			if (term.isConstant() && !term.hasSlot()) {
				return Operand.constant(constantIndex(term.constant));
			}
			if (!term.hasSlot()) {
				return null;
			}
			return slotOperand(term.slot);
		}

		private Operand slotOperand(int slot) {
			if (slot < 0 || slot >= slotColumn.length) {
				return null;
			}
			if ((entryMask >>> slot & 1L) == 1L) {
				int index = entrySlotIds.indexOf(slot);
				if (index < 0) {
					entrySlotIds.add(slot);
					index = entrySlotIds.size() - 1;
				}
				return Operand.entry(index);
			}
			if (slotColumn[slot] >= 0) {
				return Operand.col(slotColumn[slot]);
			}
			return null;
		}

		private int operandDepth(Operand operand) {
			if (operand.kind != Operand.COL) {
				return -1;
			}
			for (int slot = 0; slot < slotColumn.length; slot++) {
				if (slotColumn[slot] == operand.index) {
					return slotColumnDepth[slot];
				}
			}
			return depth();
		}

		// ------------------------------------------------------------------
		// Children
		// ------------------------------------------------------------------

		boolean lowerPattern(PatternPlan pattern) {
			openDepth();
			return lowerPatternInline(pattern);
		}

		/** Lowers a pattern into the current depth (used directly and by the multi-value seed). */
		private boolean lowerPatternInline(PatternPlan pattern) {
			if (pattern.hasRepeatedSlot() || pattern.namedContextScope || !pattern.p.isConstant()
					|| pattern.p.hasSlot() || pattern.c.hasSlot() || pattern.c.isConstant()
					|| pattern.contexts.isFixed() || pattern.s.bindConstant || pattern.o.bindConstant) {
				reason = "pattern-guards";
				return false;
			}
			// An ordered scan hint is a promise the consumer may rely on (ORDER BY satisfied by index order,
			// merge-join inputs): the kernel enumerates CSR order, which need not match — decline.
			if (pattern.statementOrder != null) {
				reason = "pattern-ordered-scan";
				return false;
			}
			// Pure-constant key with a fresh other end: materialize the single run as a key domain at bind time
			// instead of demanding a whole-predicate CSR view (a class extent needs one rdf:type run, not 84MB).
			if (pattern.s.isConstant() && !pattern.s.hasSlot() && !pattern.o.isConstant() && pattern.o.hasSlot()
					&& slotFresh(pattern.o.slot)) {
				keyDomains.add(new LmdbNativeKernelBindings.DomainRequest(pattern.p.constant, pattern.s.constant,
						true));
				currentDepthNodes().add(new LmdbNativeKernelIr.EnumerateDomain(keyDomains.size() - 1,
						newColumn(pattern.o.slot)));
				return true;
			}
			if (pattern.o.isConstant() && !pattern.o.hasSlot() && !pattern.s.isConstant() && pattern.s.hasSlot()
					&& slotFresh(pattern.s.slot)) {
				keyDomains.add(new LmdbNativeKernelBindings.DomainRequest(pattern.p.constant, pattern.o.constant,
						false));
				int column = newColumn(pattern.s.slot);
				currentDepthNodes().add(new LmdbNativeKernelIr.EnumerateDomain(keyDomains.size() - 1, column));
				assuredMask |= 1L << pattern.s.slot;
				return true;
			}
			Operand subject = operandOf(pattern.s);
			Operand object = operandOf(pattern.o);
			if (pattern.s.hasSlot()) {
				assuredMask |= 1L << pattern.s.slot;
			}
			if (subject != null && object == null && pattern.o.hasSlot()) {
				int adj = adjacency(pattern.p.constant, true, false);
				currentDepthNodes().add(new LmdbNativeKernelIr.Probe(adj, subject, newColumn(pattern.o.slot)));
				return true;
			}
			if (object != null && subject == null && pattern.s.hasSlot()) {
				int adj = adjacency(pattern.p.constant, false, false);
				currentDepthNodes().add(new LmdbNativeKernelIr.Probe(adj, object, newColumn(pattern.s.slot)));
				return true;
			}
			if (subject != null && object != null) {
				int adj = adjacency(pattern.p.constant, true, false);
				currentDepthNodes().add(new LmdbNativeKernelIr.ProbeClose(adj, subject, object, true));
				return true;
			}
			if (subject == null && object == null && pattern.s.hasSlot() && pattern.o.hasSlot()) {
				// Both endpoints fresh: enumerate the predicate's key domain. Valid at any depth — nested loops
				// make a cartesian with earlier producers exact (e.g. a single-row VALUES seed before this).
				int adj = adjacency(pattern.p.constant, true, true);
				int keyColumn = newColumn(pattern.s.slot);
				int valueColumn = newColumn(pattern.o.slot);
				currentDepthNodes().add(new LmdbNativeKernelIr.EnumerateAdjKeys(adj, keyColumn, valueColumn));
				return true;
			}
			reason = "pattern-shape";
			return false;
		}

		boolean lowerMultiValuePattern(MultiValuePatternPlan plan) {
			if (plan.fallback == null) {
				reason = "multi-value-no-fallback";
				return false;
			}
			int slot = plan.constrainedSlot;
			if (slot < 0 || (entryMask >>> slot & 1L) == 1L || slotColumn[slot] >= 0) {
				reason = "multi-value-slot-bound";
				return false;
			}
			openDepth();
			keyDomains.add(new LmdbNativeKernelBindings.DomainRequest(plan.constants.clone()));
			currentDepthNodes()
					.add(new LmdbNativeKernelIr.EnumerateDomain(keyDomains.size() - 1, newColumn(slot)));
			return lowerPatternInline(plan.fallback);
		}

		boolean lowerValues(ValuesPlan plan) {
			if (!plan.bindsAllSlotsEveryRow || Long.bitCount(plan.producedMask()) != 1) {
				reason = "values-shape";
				return false;
			}
			int slot = Long.numberOfTrailingZeros(plan.producedMask());
			if ((entryMask >>> slot & 1L) == 1L || slotColumn[slot] >= 0) {
				reason = "values-slot-bound";
				return false;
			}
			long[] domain = new long[plan.rows.length];
			for (int i = 0; i < plan.rows.length; i++) {
				ValuesRow valuesRow = plan.rows[i];
				long id = LmdbNativeAggregateCompiler.UNKNOWN;
				for (int j = 0; j < valuesRow.slots.length; j++) {
					if (valuesRow.slots[j] == slot) {
						id = valuesRow.values[j];
						break;
					}
				}
				if (id == LmdbNativeAggregateCompiler.UNKNOWN) {
					reason = "values-missing-binding";
					return false;
				}
				domain[i] = id;
			}
			openDepth();
			keyDomains.add(new LmdbNativeKernelBindings.DomainRequest(domain));
			currentDepthNodes()
					.add(new LmdbNativeKernelIr.EnumerateDomain(keyDomains.size() - 1, newColumn(slot)));
			return true;
		}

		// ------------------------------------------------------------------
		// Filters (three tiers; never a decline)
		// ------------------------------------------------------------------

		void lowerFilter(MaskedFilter masked) {
			NativeBooleanFilter filter = masked.filter;
			if (filter instanceof RecordingNativeBooleanFilter) {
				filter = ((RecordingNativeBooleanFilter) filter).delegate;
			}
			if (lowerIdFilter(filter)) {
				return;
			}
			if (lowerHookFilter(masked)) {
				return;
			}
			residualFilters.add(masked);
		}

		private boolean lowerIdFilter(NativeBooleanFilter filter) {
			if (filter instanceof OrderedSlotCompareFilter) {
				OrderedSlotCompareFilter compare = (OrderedSlotCompareFilter) filter;
				if (compare.op != Compare.CompareOp.EQ && compare.op != Compare.CompareOp.NE) {
					return false;
				}
				boolean sound = (assuredMask >>> compare.leftSlot & 1L) == 1L
						|| (assuredMask >>> compare.rightSlot & 1L) == 1L;
				Operand left = slotOperand(compare.leftSlot);
				Operand right = slotOperand(compare.rightSlot);
				if (!sound || left == null || right == null || operandMaybeNull(left)
						|| operandMaybeNull(right)) {
					return false;
				}
				placeFilter(new LmdbNativeKernelIr.FilterCompareId(compare.op == Compare.CompareOp.NE, left, right),
						Math.max(operandDepth(left), operandDepth(right)));
				return true;
			}
			if (filter instanceof CachedCompareFilter) {
				CachedCompareFilter compare = (CachedCompareFilter) filter;
				if (compare.op != Compare.CompareOp.EQ && compare.op != Compare.CompareOp.NE) {
					return false;
				}
				// safeResourceId is a pure id-type test — never materialize the constant here (tests assert
				// zero lazyValue calls on native expression paths).
				boolean sound = (assuredMask >>> compare.slot & 1L) == 1L || safeResourceId(compare.constant);
				Operand slotSide = slotOperand(compare.slot);
				if (!sound || slotSide == null || operandMaybeNull(slotSide)) {
					return false;
				}
				Operand constSide = Operand.constant(constantIndex(compare.constant));
				placeFilter(new LmdbNativeKernelIr.FilterCompareId(compare.op == Compare.CompareOp.NE, slotSide,
						constSide), operandDepth(slotSide));
				return true;
			}
			if (filter instanceof ValueSetFilter) {
				ValueSetFilter membership = (ValueSetFilter) filter;
				Operand slotSide = slotOperand(membership.slot);
				if (slotSide == null || operandMaybeNull(slotSide)) {
					return false;
				}
				int[] indices = new int[membership.accepted.length];
				for (int i = 0; i < membership.accepted.length; i++) {
					if (!safeResourceId(membership.accepted[i])) {
						return false;
					}
					indices[i] = constantIndex(membership.accepted[i]);
				}
				placeFilter(new LmdbNativeKernelIr.FilterInConstants(slotSide, indices), operandDepth(slotSide));
				return true;
			}
			return false;
		}

		private boolean lowerHookFilter(MaskedFilter masked) {
			long mask = masked.mask;
			if (mask < 0 || Long.bitCount(mask) > MAX_HOOK_ARGS) {
				return false;
			}
			int bits = Long.bitCount(mask);
			int[] argSlots = new int[bits];
			Operand[] args = new Operand[bits];
			int filterDepth = -1;
			int out = 0;
			for (int slot = 0; slot < 64; slot++) {
				if ((mask >>> slot & 1L) == 0L) {
					continue;
				}
				Operand operand = slotOperand(slot);
				if (operand == null) {
					return false;
				}
				argSlots[out] = slot;
				args[out] = operand;
				filterDepth = Math.max(filterDepth, operandDepth(operand));
				out++;
			}
			filterHooks.add(new LmdbNativeKernelBindings.FilterHook(masked, argSlots));
			placeFilter(new LmdbNativeKernelIr.FilterValue(filterHooks.size() - 1, args), filterDepth);
			return true;
		}

		private void placeFilter(Node filterNode, int filterDepth) {
			if (filterDepth < 0) {
				entryDepthFilters.add(filterNode);
			} else {
				filtersPerDepth.get(filterDepth).add(filterNode);
			}
		}

		// ------------------------------------------------------------------
		// Aggregate-side strict filters and witness sub-pipelines (plan 21)
		// ------------------------------------------------------------------

		final List<Node> witnessNodes = new ArrayList<>();
		int scratchColumns;

		/** A kernel column not backed by an engine slot: witness-local probe targets. */
		private int scratchColumn() {
			return columnEngineSlots.size() + scratchColumns++;
		}

		/** Aggregate-side filter lowering: id tier, hook tier, or witness — never residual. */
		boolean lowerFilterStrict(MaskedFilter masked) {
			NativeBooleanFilter filter = masked.filter;
			if (filter instanceof RecordingNativeBooleanFilter) {
				filter = ((RecordingNativeBooleanFilter) filter).delegate;
			}
			if (masked.mask >= 0) {
				if (lowerIdFilter(filter) || lowerHookFilter(masked)) {
					return true;
				}
				reason = "agg:filter:" + filter.getClass().getSimpleName();
				return false;
			}
			return lowerWitness(filter, false);
		}

		private boolean lowerWitness(NativeBooleanFilter filter, boolean negated) {
			if (filter instanceof RecordingNativeBooleanFilter) {
				return lowerWitness(((RecordingNativeBooleanFilter) filter).delegate, negated);
			}
			if (filter instanceof NegatedNativeBooleanFilter) {
				return lowerWitness(((NegatedNativeBooleanFilter) filter).delegate, !negated);
			}
			if (filter instanceof StatementPatternExistsFilter) {
				StatementPatternExistsFilter exists = (StatementPatternExistsFilter) filter;
				if (exists.namedContextScope || exists.contexts.isFixed() || !exists.p.isConstant()
						|| exists.p.hasSlot() || exists.c.hasSlot() || exists.c.isConstant()) {
					reason = "agg:witness-pattern-guards";
					return false;
				}
				List<Node> pipeline = new ArrayList<>(1);
				if (!lowerWitnessPattern(exists.s, exists.p.constant, exists.o, new java.util.HashMap<>(),
						pipeline)) {
					return false;
				}
				witnessNodes.add(new LmdbNativeKernelIr.Exists(negated, pipeline));
				return true;
			}
			if (filter instanceof ExistsFilter) {
				SlotPlan sub = ((ExistsFilter) filter).subPlan;
				List<Node> pipeline = new ArrayList<>();
				java.util.Map<Integer, Integer> witnessCols = new java.util.HashMap<>();
				// The sub-plan may carry its own FilterPlan wrappers (e.g. a sticky generic condition over a
				// synthetic VALUES var): peel them and lower each as a witness filter after the producers.
				List<MaskedFilter> peeled = new ArrayList<>(0);
				while (sub instanceof FilterPlan) {
					FilterPlan filterPlan = (FilterPlan) sub;
					peeled.add(new MaskedFilter(filterPlan.filter, filterPlan.filterMask));
					sub = filterPlan.arg;
				}
				if (sub instanceof PatternPlan) {
					if (!lowerWitnessPatternPlan((PatternPlan) sub, witnessCols, pipeline)) {
						return false;
					}
				} else if (sub instanceof MultiJoinPlan) {
					MultiJoinPlan subJoin = (MultiJoinPlan) sub;
					if (!lowerWitnessJoin(subJoin, witnessCols, pipeline)) {
						return false;
					}
				} else {
					reason = "agg:witness-subplan:" + sub.getClass().getSimpleName();
					return false;
				}
				for (MaskedFilter peeledFilter : peeled) {
					if (!lowerWitnessFilter(peeledFilter, witnessCols, pipeline)) {
						return false;
					}
				}
				witnessNodes.add(new LmdbNativeKernelIr.Exists(negated, pipeline));
				return true;
			}
			reason = "agg:sticky:" + filter.getClass().getSimpleName();
			return false;
		}

		/**
		 * Lowers a witness join bag with greedy connectivity ordering: the compiler's derived order is planned for the
		 * uncorrelated case (entry mask 0), so a correlated pattern may sit behind an exists-local one — pick, on each
		 * round, any remaining pattern with an available endpoint instead.
		 */
		private boolean lowerWitnessJoin(MultiJoinPlan subJoin, java.util.Map<Integer, Integer> witnessCols,
				List<Node> pipeline) {
			List<PatternPlan> remaining = new ArrayList<>();
			for (SlotPlan child : subJoin.derivedPlan(0L).order) {
				if (!(child instanceof PatternPlan)) {
					reason = "agg:witness-child:" + child.getClass().getSimpleName();
					return false;
				}
				remaining.add((PatternPlan) child);
			}
			while (!remaining.isEmpty()) {
				boolean progressed = false;
				for (int i = 0; i < remaining.size(); i++) {
					PatternPlan candidate = remaining.get(i);
					if (witnessPatternCorrelated(candidate, witnessCols)) {
						if (!lowerWitnessPatternPlan(candidate, witnessCols, pipeline)) {
							return false;
						}
						remaining.remove(i);
						progressed = true;
						break;
					}
				}
				if (!progressed) {
					reason = "agg:witness-uncorrelated";
					return false;
				}
			}
			for (MaskedFilter subFilter : subJoin.filters) {
				if (!lowerWitnessFilter(subFilter, witnessCols, pipeline)) {
					return false;
				}
			}
			return true;
		}

		/** True when at least one endpoint of the pattern is already available (probe-able) in this witness. */
		private boolean witnessPatternCorrelated(PatternPlan pattern, java.util.Map<Integer, Integer> witnessCols) {
			return witnessTermAvailable(pattern.s, witnessCols) || witnessTermAvailable(pattern.o, witnessCols);
		}

		private boolean witnessTermAvailable(Term term, java.util.Map<Integer, Integer> witnessCols) {
			if (term.isConstant() && !term.hasSlot()) {
				return true;
			}
			if (!term.hasSlot()) {
				return false;
			}
			if (witnessCols.containsKey(term.slot)) {
				return true;
			}
			return (entryMask >>> term.slot & 1L) == 1L || slotColumn[term.slot] >= 0;
		}

		private boolean lowerWitnessPatternPlan(PatternPlan pattern, java.util.Map<Integer, Integer> witnessCols,
				List<Node> pipeline) {
			if (pattern.namedContextScope || !pattern.p.isConstant() || pattern.p.hasSlot() || pattern.c.hasSlot()
					|| pattern.c.isConstant() || pattern.contexts.isFixed() || pattern.s.bindConstant
					|| pattern.o.bindConstant) {
				reason = "agg:witness-pattern-guards";
				return false;
			}
			if (pattern.hasRepeatedSlot()) {
				// Self-loop witness (?x pred ?x): expressible as a semi ProbeClose with both ends the same operand.
				if (pattern.s.hasSlot() && pattern.o.hasSlot() && pattern.s.slot == pattern.o.slot) {
					Operand endpoint = witnessOperand(pattern.s, witnessCols);
					if (endpoint != null) {
						int adj = adjacency(pattern.p.constant, true, false);
						pipeline.add(new LmdbNativeKernelIr.ProbeClose(adj, endpoint, endpoint, false));
						return true;
					}
				}
				reason = "agg:witness-repeated-slot";
				return false;
			}
			return lowerWitnessPattern(pattern.s, pattern.p.constant, pattern.o, witnessCols, pipeline);
		}

		/**
		 * A filter inside a witness body: hook-tier only in this tier — the callback evaluates the exact interpreted
		 * filter against the witness-local values, so semantics are engine-exact at any position after the producers.
		 */
		private boolean lowerWitnessFilter(MaskedFilter masked, java.util.Map<Integer, Integer> witnessCols,
				List<Node> pipeline) {
			NativeBooleanFilter filter = masked.filter;
			if (filter instanceof RecordingNativeBooleanFilter) {
				filter = ((RecordingNativeBooleanFilter) filter).delegate;
			}
			long mask = masked.mask;
			if (mask < 0 || Long.bitCount(mask) > MAX_HOOK_ARGS) {
				reason = "agg:witness-filter-mask";
				return false;
			}
			int bits = Long.bitCount(mask);
			int[] argSlots = new int[bits];
			Operand[] args = new Operand[bits];
			int out = 0;
			for (int slot = 0; slot < 64; slot++) {
				if ((mask >>> slot & 1L) == 0L) {
					continue;
				}
				Integer witnessLocal = witnessCols.get(slot);
				Operand operand = witnessLocal != null ? Operand.col(witnessLocal) : slotOperand(slot);
				if (operand == null) {
					reason = "agg:witness-filter-slot";
					return false;
				}
				argSlots[out] = slot;
				args[out] = operand;
				out++;
			}
			filterHooks.add(new LmdbNativeKernelBindings.FilterHook(masked, argSlots));
			pipeline.add(new LmdbNativeKernelIr.FilterValue(filterHooks.size() - 1, args));
			return true;
		}

		/**
		 * One witness pattern: available endpoints (outer columns/entries/constants or earlier witness-local columns)
		 * correlate; fresh endpoints become witness-local scratch columns produced by the probe.
		 */
		private boolean lowerWitnessPattern(Term s, long predicate, Term o,
				java.util.Map<Integer, Integer> witnessCols, List<Node> pipeline) {
			Operand subject = witnessOperand(s, witnessCols);
			Operand object = witnessOperand(o, witnessCols);
			if (subject != null && object != null) {
				int adj = adjacency(predicate, true, false);
				pipeline.add(new LmdbNativeKernelIr.ProbeClose(adj, subject, object, false));
				return true;
			}
			// Existential endpoints may carry a slot (readable by later witness patterns) or be fully anonymous.
			if (subject != null && !o.isConstant()) {
				int adj = adjacency(predicate, true, false);
				int column = scratchColumn();
				if (o.hasSlot()) {
					witnessCols.put(o.slot, column);
				}
				pipeline.add(new LmdbNativeKernelIr.Probe(adj, subject, column));
				return true;
			}
			if (object != null && !s.isConstant()) {
				int adj = adjacency(predicate, false, false);
				int column = scratchColumn();
				if (s.hasSlot()) {
					witnessCols.put(s.slot, column);
				}
				pipeline.add(new LmdbNativeKernelIr.Probe(adj, object, column));
				return true;
			}
			reason = "agg:witness-uncorrelated";
			return false;
		}

		/**
		 * MINUS arm as an anti-join witness: left rows survive only when no right row is compatible on the shared
		 * (correlated) variables. Correlation happens naturally: shared slots resolve to outer columns, right-only
		 * slots become witness-local scratch columns.
		 */
		boolean lowerMinusArm(SlotPlan arm) {
			List<Node> pipeline = new ArrayList<>();
			java.util.Map<Integer, Integer> witnessCols = new java.util.HashMap<>();
			// BIND extensions only add bindings — existence under the anti-join is unaffected, so peel them.
			while (arm instanceof ExtensionPlan) {
				arm = ((ExtensionPlan) arm).arg;
			}
			if (arm instanceof PatternPlan) {
				if (!lowerWitnessPatternPlan((PatternPlan) arm, witnessCols, pipeline)) {
					return false;
				}
			} else if (arm instanceof MultiJoinPlan) {
				if (!lowerWitnessJoin((MultiJoinPlan) arm, witnessCols, pipeline)) {
					return false;
				}
			} else {
				reason = "agg:minus-arm:" + arm.getClass().getSimpleName();
				return false;
			}
			witnessNodes.add(new LmdbNativeKernelIr.Exists(true, pipeline));
			return true;
		}

		private Operand witnessOperand(Term term, java.util.Map<Integer, Integer> witnessCols) {
			if (term.isConstant() && !term.hasSlot()) {
				return Operand.constant(constantIndex(term.constant));
			}
			if (!term.hasSlot()) {
				return null;
			}
			Integer witnessLocal = witnessCols.get(term.slot);
			if (witnessLocal != null) {
				return Operand.col(witnessLocal);
			}
			Operand outer = slotOperand(term.slot);
			// Correlating a witness on a maybe-null column would need scan semantics when null — treat as
			// unavailable; the pattern-level fallthrough then declines the witness.
			return outer != null && operandMaybeNull(outer) ? null : outer;
		}

		Lowered buildAggregate(int[] groupSlots, AggregateSpec[] aggregates) {
			int[] groupCols = new int[groupSlots.length];
			for (int i = 0; i < groupSlots.length; i++) {
				if (groupSlots[i] < 0 || groupSlots[i] >= slotColumn.length || slotColumn[groupSlots[i]] < 0) {
					reason = "agg:group-slot-unavailable";
					return null;
				}
				groupCols[i] = slotColumn[groupSlots[i]];
			}
			LmdbNativeKernelIr.AggregateOutput[] outputs = new LmdbNativeKernelIr.AggregateOutput[aggregates.length];
			LmdbNativeKernelBindings.AggOut[] outs = new LmdbNativeKernelBindings.AggOut[aggregates.length];
			boolean hooksRequired = false;
			boolean sumGuard = false;
			for (int i = 0; i < aggregates.length; i++) {
				AggregateSpec spec = aggregates[i];
				if (spec.kind == AggKind.COUNT && spec.slot < 0 && !spec.distinct
						&& spec.constant == LmdbNativeAggregateCompiler.UNKNOWN) {
					outputs[i] = LmdbNativeKernelIr.AggregateOutput.countStar();
					outs[i] = new LmdbNativeKernelBindings.AggOut(spec, LmdbNativeKernelBindings.ENC_LONG_COUNT);
					continue;
				}
				if (spec.slot < 0 || spec.slot >= slotColumn.length || slotColumn[spec.slot] < 0) {
					reason = "agg:input-unavailable";
					return null;
				}
				int col = slotColumn[spec.slot];
				switch (spec.kind) {
				case COUNT:
					outputs[i] = spec.distinct ? LmdbNativeKernelIr.AggregateOutput.countDistinct(col)
							: LmdbNativeKernelIr.AggregateOutput.count(col);
					outs[i] = new LmdbNativeKernelBindings.AggOut(spec, LmdbNativeKernelBindings.ENC_LONG_COUNT);
					break;
				case SUM:
					if (spec.distinct) {
						reason = "agg:sum-distinct";
						return null;
					}
					outputs[i] = LmdbNativeKernelIr.AggregateOutput.sum(col);
					outs[i] = new LmdbNativeKernelBindings.AggOut(spec,
							LmdbNativeKernelBindings.ENC_SUM_DOUBLE_BITS);
					hooksRequired = true;
					sumGuard = true;
					break;
				case MIN:
					outputs[i] = LmdbNativeKernelIr.AggregateOutput.minId(col);
					outs[i] = new LmdbNativeKernelBindings.AggOut(spec, LmdbNativeKernelBindings.ENC_VALUE_ID);
					hooksRequired = true;
					break;
				case MAX:
					outputs[i] = LmdbNativeKernelIr.AggregateOutput.maxId(col);
					outs[i] = new LmdbNativeKernelBindings.AggOut(spec, LmdbNativeKernelBindings.ENC_VALUE_ID);
					hooksRequired = true;
					break;
				default: // AVG (decimal-division semantics) — declined in this tier
					reason = "agg:" + spec.kind;
					return null;
				}
			}
			List<Node> pipeline = new ArrayList<>(entryDepthFilters);
			for (int d = 0; d < nodesPerDepth.size(); d++) {
				pipeline.addAll(nodesPerDepth.get(d));
				pipeline.addAll(filtersPerDepth.get(d));
			}
			pipeline.addAll(witnessNodes);
			int columnCount = columnEngineSlots.size() + scratchColumns;
			if (columnCount == 0 || columnCount > 64) {
				reason = "agg:no-columns";
				return null;
			}
			Kernel kernel = new Kernel(columnCount, pipeline,
					new LmdbNativeKernelIr.Aggregate(groupCols, outputs, null, LmdbNativeKernelIr.OutputMods.none()));
			long[] constantArray = new long[constants.size()];
			for (int i = 0; i < constantArray.length; i++) {
				constantArray[i] = constants.get(i);
			}
			int[] entryArray = new int[entrySlotIds.size()];
			for (int i = 0; i < entryArray.length; i++) {
				entryArray[i] = entrySlotIds.get(i);
			}
			int[] columnArray = new int[columnEngineSlots.size()];
			for (int i = 0; i < columnArray.length; i++) {
				columnArray[i] = columnEngineSlots.get(i);
			}
			LmdbNativeKernelBindings bindings = new LmdbNativeKernelBindings(
					adjacencies.toArray(new LmdbNativeKernelBindings.AdjacencyRequest[0]), constantArray, entryArray,
					keyDomains.toArray(new LmdbNativeKernelBindings.DomainRequest[0]),
					filterHooks.toArray(new LmdbNativeKernelBindings.FilterHook[0]), columnArray, residualFilters,
					new LmdbNativeKernelBindings.KernelGroupLayout(groupSlots.clone(), outs), hooksRequired,
					sumGuard);
			return new Lowered(kernel, bindings);
		}

		// ------------------------------------------------------------------
		// Assembly
		// ------------------------------------------------------------------

		Lowered build() {
			if (columnEngineSlots.isEmpty() || columnEngineSlots.size() > 64) {
				return null;
			}
			List<Node> pipeline = new ArrayList<>(entryDepthFilters);
			for (int d = 0; d < nodesPerDepth.size(); d++) {
				pipeline.addAll(nodesPerDepth.get(d));
				pipeline.addAll(filtersPerDepth.get(d));
			}
			int[] emitColumns = new int[columnEngineSlots.size()];
			for (int i = 0; i < emitColumns.length; i++) {
				emitColumns[i] = i;
			}
			Kernel kernel = new Kernel(columnEngineSlots.size(), pipeline,
					new LmdbNativeKernelIr.Emit(emitColumns, false, LmdbNativeKernelIr.OutputMods.none()));

			long[] constantArray = new long[constants.size()];
			for (int i = 0; i < constantArray.length; i++) {
				constantArray[i] = constants.get(i);
			}
			int[] entryArray = new int[entrySlotIds.size()];
			for (int i = 0; i < entryArray.length; i++) {
				entryArray[i] = entrySlotIds.get(i);
			}
			int[] columnArray = new int[columnEngineSlots.size()];
			for (int i = 0; i < columnArray.length; i++) {
				columnArray[i] = columnEngineSlots.get(i);
			}
			LmdbNativeKernelBindings bindings = new LmdbNativeKernelBindings(
					adjacencies.toArray(new LmdbNativeKernelBindings.AdjacencyRequest[0]), constantArray, entryArray,
					keyDomains.toArray(new LmdbNativeKernelBindings.DomainRequest[0]),
					filterHooks.toArray(new LmdbNativeKernelBindings.FilterHook[0]), columnArray, residualFilters);
			return new Lowered(kernel, bindings);
		}
	}
}
